as_sql.definition:
{% if val is none %}
    NULL
{% else %}
    {% set v = val | trim %}
    {% if v.startswith("'") and v.endswith("'") %}
        {% set v = v[1:-1] %}
    {% endif %}
    {% if v.startswith('"') and v.endswith('"') %}
        {% set v = v[1:-1] %}
    {% endif %}
    {% set v = v | replace("\\'", "'") | replace('\\"', '"') | replace("''", "'") %}

    {{ v }}
{% endif %}
